(self.webpackChunkvuepress_blog=self.webpackChunkvuepress_blog||[]).push([[58],{3899:(n,s,a)=>{"use strict";a.r(s),a.d(s,{data:()=>e});const e={key:"v-2d46f422",path:"/pages/ai-energize/code-review/",title:"研发规范",lang:"zh-CN",frontmatter:{},excerpt:"",headers:[{level:2,title:"1. 编码规范",slug:"_1-编码规范",children:[{level:3,title:"1.1 布尔值映射与空值",slug:"_1-1-布尔值映射与空值",children:[]},{level:3,title:"1.2 对象扩展符的字段覆盖风险",slug:"_1-2-对象扩展符的字段覆盖风险",children:[]},{level:3,title:"1.3 原生 enum 的默认枚举值风险",slug:"_1-3-原生-enum-的默认枚举值风险",children:[]}]},{level:2,title:"Code Review 检查清单",slug:"code-review-检查清单-1",children:[]}],filePathRelative:"pages/ai-energize/code-review/README.md",git:{updatedTime:1776756909e3,contributors:[{name:"COOKIES-LGL",email:"1344714332@qq.com",commits:1}]}}},122:(n,s,a)=>{"use strict";a.r(s),a.d(s,{default:()=>p});const e=(0,a(6252).uE)('<h1 id="研发规范"><a class="header-anchor" href="#研发规范">#</a> 研发规范</h1><p><strong>数据准确性优先级最高</strong>：展示文案、请求参数、类型以及兜底逻辑都必须与业务语义一致，避免误导用户或引发线上事故。</p><hr><h2 id="_1-编码规范"><a class="header-anchor" href="#_1-编码规范">#</a> 1. 编码规范</h2><h3 id="_1-1-布尔值映射与空值"><a class="header-anchor" href="#_1-1-布尔值映射与空值">#</a> 1.1 布尔值映射与空值</h3><p>当后端返回的是<strong>布尔值</strong>，你要把它映射为“生效 / 失效”等文案时，必须<strong>显式处理 <code>0</code> / <code>null</code> / <code>undefined</code></strong>。普通三元表达式 <code>v ? &#39;A&#39; : &#39;B&#39;</code> 会把 <code>null</code> \\ <code>0</code> \\ <code>undefined</code> 当作 falsy，这在你的业务里未必等于“失效”，提示用户注意 <code>0</code> 值。</p><p><strong>反例：</strong></p><div class="language-javascript ext-js line-numbers-mode"><pre class="language-javascript"><code><span class="token punctuation">{</span>\n  key<span class="token operator">:</span> <span class="token string">&#39;isEffective&#39;</span><span class="token punctuation">,</span>\n  title<span class="token operator">:</span> <span class="token string">&#39;Quote status&#39;</span><span class="token punctuation">,</span>\n  width<span class="token operator">:</span> <span class="token number">120</span><span class="token punctuation">,</span>\n  <span class="token function-variable function">transform</span><span class="token operator">:</span> <span class="token parameter">v</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span>v <span class="token operator">?</span> <span class="token string">&#39;Active&#39;</span> <span class="token operator">:</span> <span class="token string">&#39;Inactive&#39;</span><span class="token punctuation">)</span> <span class="token comment">// null、0、undefined also shows &#39;Inactive&#39;</span>\n<span class="token punctuation">}</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>建议：</strong> 与产品确认 <code>null</code> 的业务语义；常见模式是 <code>null</code>/<code>undefined</code> 展示为 <code>--</code>，仅对 <code>true</code>/<code>false</code> 做标签映射。</p><hr><h3 id="_1-2-对象扩展符的字段覆盖风险"><a class="header-anchor" href="#_1-2-对象扩展符的字段覆盖风险">#</a> 1.2 对象扩展符的字段覆盖风险</h3><p>在使用对象扩展符合并对象时，需要注意字段覆盖的顺序。后面的属性会覆盖前面的同名属性，这可能导致意外的数据覆盖。</p><p><strong>反例：</strong></p><div class="language-typescript ext-ts line-numbers-mode"><pre class="language-typescript"><code><span class="token keyword">const</span> <span class="token function-variable function">handleFormatList</span> <span class="token operator">=</span> <span class="token punctuation">(</span>priceConfigList<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> res<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n  <span class="token keyword">const</span> <span class="token punctuation">{</span> systemYardName<span class="token punctuation">,</span> effectiveMonth <span class="token punctuation">}</span> <span class="token operator">=</span> res <span class="token operator">||</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span>\n\n  <span class="token keyword">const</span> listTemp <span class="token operator">=</span> priceConfigList<span class="token operator">?.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n    <span class="token keyword">return</span> <span class="token punctuation">{</span>\n      systemYardName<span class="token punctuation">,</span>\n      effectiveMonth<span class="token punctuation">,</span>\n      <span class="token operator">...</span>item<span class="token punctuation">,</span> <span class="token comment">// ❌ item如果 item 中有同名字段，会覆盖前面的值</span>\n    <span class="token punctuation">}</span><span class="token punctuation">;</span>\n  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n  <span class="token keyword">return</span> listTemp <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>\n<span class="token punctuation">}</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><strong>问题分析：</strong></p><ol><li><strong>字段覆盖风险</strong>：如果后端 API 变更，在 <code>PriceConfigListItem</code> 中添加了 <code>systemYardName</code> 或 <code>effectiveMonth</code> 字段，就会发生字段覆盖，导致从 <code>res</code> 中获取的值被 <code>item</code> 中的值覆盖。</li></ol><p><strong>建议：</strong></p><div class="language-typescript ext-ts line-numbers-mode"><pre class="language-typescript"><code><span class="token keyword">const</span> <span class="token function-variable function">handleFormatList</span> <span class="token operator">=</span> <span class="token punctuation">(</span>priceConfigList<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> res<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>\n  <span class="token keyword">const</span> <span class="token punctuation">{</span> systemYardName<span class="token punctuation">,</span> effectiveMonth <span class="token punctuation">}</span> <span class="token operator">=</span> res <span class="token operator">||</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span>\n\n  <span class="token keyword">const</span> listTemp <span class="token operator">=</span> priceConfigList<span class="token operator">?.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span>\n    <span class="token operator">...</span>item<span class="token punctuation">,</span> <span class="token comment">//  ✅ 先展开 item</span>\n    systemYardName<span class="token punctuation">,</span> <span class="token comment">// 再覆盖，确保 res 的字段优先级更高</span>\n    effectiveMonth<span class="token punctuation">,</span>\n  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>\n\n  <span class="token keyword">return</span> listTemp <span class="token operator">??</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>\n<span class="token punctuation">}</span><span class="token punctuation">;</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>改进后的优势：</strong></p><ol><li><strong>防止字段覆盖</strong>：将 <code>...item</code> 放在前面，确保 <code>res</code> 的字段优先级更高，即使 <code>item</code> 中有同名字段也不会被覆盖</li><li><strong>代码更简洁</strong>：使用隐式返回，减少冗余代码</li></ol><p><strong>扩展符覆盖规则：</strong></p><div class="language-typescript ext-ts line-numbers-mode"><pre class="language-typescript"><code><span class="token comment">// 后面的属性会覆盖前面的同名属性</span>\n<span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token punctuation">{</span>\n  a<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>\n  b<span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span>\n  <span class="token operator">...</span><span class="token punctuation">{</span> a<span class="token operator">:</span> <span class="token number">3</span><span class="token punctuation">,</span> c<span class="token operator">:</span> <span class="token number">4</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token comment">// a 会被覆盖为 3</span>\n<span class="token punctuation">}</span><span class="token punctuation">;</span>\n<span class="token comment">// result = { a: 3, b: 2, c: 4 }</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h3 id="_1-3-原生-enum-的默认枚举值风险"><a class="header-anchor" href="#_1-3-原生-enum-的默认枚举值风险">#</a> 1.3 原生 <code>enum</code> 的默认枚举值风险</h3><p>当使用 TypeScript 原生 <code>enum</code> 的默认枚举值时,如果在第一个位置添加新枚举值,会导致后续所有枚举值发生变化,造成严重的兼容性问题。</p><h4 id="错误示例"><a class="header-anchor" href="#错误示例">#</a> 错误示例</h4><div class="language-typescript ext-ts line-numbers-mode"><pre class="language-typescript"><code><span class="token comment">// ❌ 危险:使用默认枚举值</span>\n<span class="token keyword">export</span> <span class="token keyword">enum</span> Status <span class="token punctuation">{</span>\n  <span class="token constant">PENDING</span><span class="token punctuation">,</span> <span class="token comment">// 0</span>\n  <span class="token constant">PROCESSING</span><span class="token punctuation">,</span> <span class="token comment">// 1</span>\n  <span class="token constant">COMPLETED</span><span class="token punctuation">,</span> <span class="token comment">// 2</span>\n<span class="token punctuation">}</span>\n\n<span class="token comment">// 如果在第一个位置添加新枚举值</span>\n<span class="token keyword">export</span> <span class="token keyword">enum</span> Status <span class="token punctuation">{</span>\n  <span class="token constant">DRAFT</span><span class="token punctuation">,</span> <span class="token comment">// 0 (新增)</span>\n  <span class="token constant">PENDING</span><span class="token punctuation">,</span> <span class="token comment">// 1 (原为 0)</span>\n  <span class="token constant">PROCESSING</span><span class="token punctuation">,</span> <span class="token comment">// 2 (原为 1)</span>\n  <span class="token constant">COMPLETED</span><span class="token punctuation">,</span> <span class="token comment">// 3 (原为 2)</span>\n<span class="token punctuation">}</span>\n\n<span class="token comment">// 所有依赖 Status.PENDING (值为 0) 的代码都会出错!</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h4 id="正确做法"><a class="header-anchor" href="#正确做法">#</a> 正确做法</h4><p><strong>方案 1: 显式指定所有枚举值</strong></p><div class="language-typescript ext-ts line-numbers-mode"><pre class="language-typescript"><code><span class="token comment">// ✅ 推荐:显式指定所有枚举值</span>\n<span class="token keyword">export</span> <span class="token keyword">enum</span> Status <span class="token punctuation">{</span>\n  <span class="token constant">PENDING</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span>\n  <span class="token constant">PROCESSING</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span>\n  <span class="token constant">COMPLETED</span> <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">,</span>\n<span class="token punctuation">}</span>\n\n<span class="token comment">// 添加新枚举值时,在末尾添加</span>\n<span class="token keyword">export</span> <span class="token keyword">enum</span> Status <span class="token punctuation">{</span>\n  <span class="token constant">PENDING</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span>\n  <span class="token constant">PROCESSING</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span>\n  <span class="token constant">COMPLETED</span> <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">,</span>\n  <span class="token constant">DRAFT</span> <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token comment">// 新增在末尾</span>\n<span class="token punctuation">}</span>\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h4 id="code-review-检查清单"><a class="header-anchor" href="#code-review-检查清单">#</a> Code Review 检查清单</h4><p>在 Code Review 时,对于所有 <code>enum</code> 定义,必须检查:</p><ul><li>[ ] <strong>禁止使用默认枚举值</strong>: 所有枚举成员必须显式指定值</li><li>[ ] <strong>数值枚举</strong>: 必须为每个成员指定明确的数字值</li><li>[ ] <strong>新增枚举值</strong>: 必须添加在枚举定义的末尾,避免影响现有值</li><li>[ ] <strong>向后兼容</strong>: 修改现有枚举时,确保不改变已有枚举成员的值</li></ul><h2 id="code-review-检查清单-1"><a class="header-anchor" href="#code-review-检查清单-1">#</a> Code Review 检查清单</h2><table><thead><tr><th>领域</th><th>关注点</th></tr></thead><tbody><tr><td>API 与 URL</td><td>枚举复用与权限；校验 URL 参数；警惕 <code>Number</code> → <code>0</code></td></tr><tr><td>对象操作</td><td>扩展符字段覆盖风险</td></tr><tr><td>默认枚举值风险</td><td>禁止使用默认枚举值；显式指定所有枚举值</td></tr></tbody></table>',35),p={render:function(n,s){return e}}}}]);